/* ---- daily price refresh ---- */
const EMBED={stocks:DATA0,btc:BTC0,end:{stock:"2026-10-16",btc:"2026-10-17"}};
const KEY="csvb-prices-v1";
const berlinDay=()=>new Intl.DateTimeFormat("en-CA",{timeZone:"Europe/Berlin"}).format(new Date());
const longDate=iso=>{const d=new Date(Date.parse(iso));return d.getUTCDate()+" "+MN[d.getUTCMonth()]+" "+d.getUTCFullYear();};
function store(){try{return JSON.parse(localStorage.getItem(KEY))||null;}catch(e){return null;}}
function save(v){try{localStorage.setItem(KEY,JSON.stringify(v));}catch(e){}}
/* take the fresh series where they are complete, keep the built-in ones otherwise */
function merge(api){
  const stocks=Object.assign({},EMBED.stocks); let fresh=0;
  if(api&&api.stocks)Object.keys(EMBED.stocks).forEach(id=>{const n=api.stocks[id],o=EMBED.stocks[id];
    if(Array.isArray(n)&&n[0]===o[0]&&Array.isArray(n[1])&&n[1].length>=o[1].length&&n[1].every(v=>typeof v==="number"&&v>0)){stocks[id]=n;fresh++;}});
  let btc=EMBED.btc;
  if(api&&Array.isArray(api.btc)&&api.btc.length>=EMBED.btc.trim().split("\n").length&&api.btc[0][0]===1728518400&&api.btc.every(r=>Array.isArray(r)&&Number.isFinite(r[0])&&Number.isFinite(r[1])&&r[1]>0))btc=api.btc.map(r=>r[0]+","+r[1]).join("\n");
  const okDate=v=>typeof v==="string"&&/^\d{4}-\d{2}-\d{2}$/.test(v)&&!isNaN(Date.parse(v));
  const stockEnd=api&&okDate(api.stockEnd)&&api.stockEnd>EMBED.end.stock&&fresh?api.stockEnd:EMBED.end.stock;
  const btcEnd=btc!==EMBED.btc&&okDate(api.btcEnd)?api.btcEnd:EMBED.end.btc;
  return {stocks,btc,end:{stock:stockEnd,btc:btcEnd}};
}
function show(d){
  boot(d.stocks,d.btc,d.end);
  document.getElementById("asof").textContent="Prices as of "+longDate(d.end.stock);
  document.getElementById("asof-foot").textContent="The last stock point is the week to "+longDate(d.end.stock)+"; the last Bitcoin point is a partial week as quoted on "+longDate(d.end.btc)+".";
}
const btn=document.getElementById("refresh"), msg=document.getElementById("refresh-msg");
function syncBtn(){const s=store(),done=!!(s&&s.day===berlinDay());btn.disabled=done;btn.textContent=done?"Refreshed today":"Refresh prices";}
let shown=EMBED;
(function(){const s=store();if(s&&s.data){const m=merge(s.data);if(m.end.stock>=EMBED.end.stock)shown=m;}})();
show(shown); syncBtn();
btn.onclick=async()=>{
  const today=berlinDay(); const s=store(); if(s&&s.day===today)return;
  btn.disabled=true; btn.textContent="Refreshing…"; msg.textContent="";
  try{
    const r=await fetch("/api/prices?day="+today,{headers:{Accept:"application/json"}});
    if(!r.ok)throw new Error("status "+r.status);
    const api=await r.json(); const m=merge(api);
    save({day:today,data:api});
    if(m.end.stock>shown.end.stock||m.end.btc>shown.end.btc){shown=m;show(m);msg.textContent="Updated to the latest available prices.";}
    else msg.textContent="No newer prices yet. The data is already current.";
  }catch(e){msg.textContent="Couldn't load new prices right now. The page still shows the data up to "+longDate(shown.end.stock)+". Try again later.";btn.disabled=false;btn.textContent="Refresh prices";return;}
  syncBtn();
};
